<template>
  <section class="flex flex-col gap-4">
    <PageTitle title="System Dashboard">
      <FilterTabsNav :items="navigationItems" rounded />
    </PageTitle>
    <NuxtPage />
  </section>
</template>

<script setup lang="ts">
import type { NavigationItem } from '~/types/projects';

definePageMeta({
  roles: ['admin'],
});

const route = useRoute();

useHead({
  title: 'System Dashboard',
});

const tabs: Array<{ label: string; routeName: string }> = [
  { label: 'Overview', routeName: 'system-dashboard-overview' },
  { label: 'Signature Projects', routeName: 'system-dashboard-signature-projects' },
  { label: 'Canvassing Projects', routeName: 'system-dashboard-canvassing-projects' },
  { label: 'Users and Hiring', routeName: 'system-dashboard-users-and-hiring' },
  { label: 'Recruitment', routeName: 'system-dashboard-recruitment' },
  { label: 'Reports and Fraud', routeName: 'system-dashboard-reports-and-fraud' },
  { label: 'Payments', routeName: 'system-dashboard-payments' },
  { label: 'Payroll', routeName: 'system-dashboard-payroll' },
];

const dateQuery = computed(() => {
  const query: Record<string, string> = {};
  if (route.query.start_date) query.start_date = route.query.start_date.toString();
  if (route.query.end_date) query.end_date = route.query.end_date.toString();
  return query;
});

const navigationItems = computed<NavigationItem[]>(() =>
  tabs.map((tab) => ({
    label: tab.label,
    to: { name: tab.routeName, query: dateQuery.value },
    selected: route.name === tab.routeName,
  }))
);
</script>
